import * as fs from 'fs';

/**
 * The program reads a CSV file containing employee data, calculates 
 * department-specific statistics, identifies the highest-paid employee,
 * filters departments with more than 2 employees, and calculates the 
 * total budget.
 */

const filePath = '/tmp/…/employees.csv';

/**
 * Formats a number as a currency string with optional decimal places.
 * @param num The number to format.
 * @param decimals The number of decimal places to show.
 * @returns A string formatted as $XX,XXX.XX
 */
function formatCurrency(num: number, decimals: number): string {
    const formatted = num.toLocaleString('en-US', {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals,
    });
    return `$${formatted}`;
}

function main() {
    try {
        // Read the CSV file content
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.trim().split(/\r?\n/);

        if (lines.length < 2) {
            return;
        }

        // Parse CSV rows (skip header)
        const rows = lines.slice(1).map(line => {
            const parts = line.split(',').map(p => p.trim());
            return {
                id: parts[0],
                name: parts[1],
                department: parts[2],
                salary: parseFloat(parts[3]),
                startDate: parts[4],
                rating: parts[5]
            };
        });

        const deptStats: Record<string, { totalSalary: number; count: number }> = {};
        let highestPaidEmployee: any = rows[0];
        let totalBudget = 0;

        // Aggregate data
        rows.forEach(emp => {
            if (!deptStats[emp.department]) {
                deptStats[emp.department] = { totalSalary: 0, count: 0 };
            }
            deptStats[emp.department].totalSalary += emp.salary;
            deptStats[emp.department].count += 1;

            if (emp.salary > highestPaidEmployee.salary) {
                highestPaidEmployee = emp;
            }
            totalBudget += emp.salary;
        });

        // Output Report
        console.log("=== Salary Report ===");
        console.log("");

        console.log("Average Salary by Department:");
        const sortedDepts = Object.keys(deptStats).sort();
        sortedDepts.forEach(dept => {
            const stats = deptStats[dept];
            const avg = stats.totalSalary / stats.count;
            console.log(`  ${dept}: ${formatCurrency(avg, 2)}`);
        });

        console.log("");
        console.log(`Highest Paid: ${highestPaidEmployee.name} (${formatCurrency(highestPaidEmployee.salary, 0)})`);

        console.log("");
        console.log("Departments with >2 employees:");
        const moreThanTwo = Object.keys(deptStats)
            .filter(dept => deptStats[dept].count > 2)
            .sort();
        moreThanTwo.forEach(dept => {
            console.log(`  ${dept} (${deptStats[dept].count} employees)`);
        });

        console.log("");
        console.log(`Total Budget: ${formatCurrency(totalBudget, 0)}`);

    } catch (err) {
        // Silent fail or handle as necessary
    }
}

