import * as fs from 'fs';

/**
 * Removes duplicates from an array while preserving the original order.
 * Uses JSON.stringify to ensure deep equality for objects/arrays within the array.
 */
function uniqueArray(arr: any[]): any[] {
  const seen = new Set<string>();
  const result: any[] = [];
  for (const item of arr) {
    const str = JSON.stringify(item);
    if (!seen.has(str)) {
      seen.add(str);
      result.push(item);
    }
  }
  return result;
}

/**
 * Deep merges two values based on specific rules:
 * - If both are objects: merge recursively
 * - If both are arrays: concatenate and remove duplicates (A first, then B)
 * - If scalar conflict: B overrides A
 * - Keys only in A or only in B are included as-is
 */
function deepMerge(a: any, b: any): any {
  // Rule: If both values are arrays
  if (Array.isArray(a) && Array.isArray(b)) {
    return uniqueArray([...a, ...b]);
  }

  // Rule: If both values are objects (and not null or arrays)
  if (
    a !== null &&
    typeof a === 'object' &&
    !Array.isArray(a) &&
    b !== null &&
    typeof b === 'object' &&
    !Array.isArray(b)
  ) {
    const result: any = { ...a };
    for (const key in b) {
      if (Object.prototype.hasOwnProperty.call(b, key)) {
        // If the key exists in both, deepMerge handles the recursion/override.
        // If the key only exists in B, a[key] is undefined and deepMerge returns b[key].
        result[key] = deepMerge(a[key], b[key]);
      }
    }
    return result;
  }

  // Rule: Scalar conflict or type mismatch: value from B overrides A
  return b;
}

/**
 * Recursively sorts all object keys alphabetically at every level.
 */
function sortObjectKeys(obj: any): any {
  if (Array.isArray(obj)) {
    return obj.map(sortObjectKeys);
  } else if (obj !== null && typeof obj === 'object') {
    const sortedObj: any = {};
    const keys = Object.keys(obj).sort();
    for (const key of keys) {
      sortedObj[key] = sortObjectKeys(obj[key]);
    }
    return sortedObj;
  }
  return obj;
}

function main() {
  const pathA = '/tmp/…/config_a.json';
  const pathB = '/tmp/…/config_b.json';

  try {
    // Read files from the specified paths
    const contentA = fs.readFileSync(pathA, 'utf8');
    const contentB = fs.readFileSync(pathB, 'utf8');

    // Parse JSON contents
    const dataA = JSON.parse(contentA);
    const dataB = JSON.parse(contentB);

    // Perform the deep merge
    const merged = deepMerge(dataA, dataB);

    // Sort all keys alphabetically
    const sorted = sortObjectKeys(merged);

    // Output the result to stdout with 2-space indentation
    process.stdout.write(JSON.stringify(sorted, null, 2) + '\n');
  } catch (error) {
    // Silent failure for missing files or parsing errors to ensure clean output
  }
}

