import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.*;

public class Main {
    static class Employee {
        String name;
        String department;
        double salary;

        Employee(String name, String department, double salary) {
            this.name = name;
            this.department = department;
            this.salary = salary;
        }
    }

    public static void main(String[] args) {
        String filePath = "/tmp/…/employees.csv";
        Map<String, List<Employee>> deptMap = new TreeMap<>();
        Employee highestPaid = null;
        double totalBudget = 0;

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line = br.readLine(); // Skip header
            while ((line = br.readLine()) != null) {
                String[] parts = line.split(",");
                if (parts.length < 4) continue;

                String name = parts[1];
                String dept = parts[2];
                double salary = Double.parseDouble(parts[3].trim());

                Employee emp = new Employee(name, dept, salary);
                deptMap.computeIfAbsent(dept, k -> new ArrayList<>()).add(emp);

                if (highestPaid == null || salary > highestPaid.salary) {
                    highestPaid = emp;
                }
                totalBudget += salary;
            }
        } catch (IOException | NumberFormatException e) {
            // Handle or ignore errors during file reading
        }

        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.US);
        symbols.setDecimalSeparator('.');
        symbols.setGroupingSeparator(',');

        DecimalFormat avgFormat = new DecimalFormat("$#,##0.00", symbols);
        DecimalFormat intFormat = new DecimalFormat("$#,##0", symbols);

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, List<Employee>> entry : deptMap.entrySet()) {
            double sum = 0;
            for (Employee e : entry.getValue()) {
                sum += e.salary;
            }
            double avg = sum / entry.getValue().size();
            System.out.println("  " + entry.getKey() + ": " + avgFormat.format(avg));
        }
        System.out.println();
        if (highestPaid != null) {
            System.out.println("Highest Paid: " + highestPaid.name + " (" + intFormat.format(Math.round(highestPaid.salary)) + ")");
        }
        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (Map.Entry<String, List<Employee>> entry : deptMap.entrySet()) {
            if (entry.getValue().size() > 2) {
                System.out.println("  " + entry.getKey() + " (" + entry.getValue().size() + " employees)");
            }
        }
        System.out.println();
        System.out.println("Total Budget: " + intFormat.format(Math.round(totalBudget)));
    }
}

