let filePath = "/tmp/…/employees.csv"

struct Employee {
    let name: String
    let department: String
    let salary: Double
}

var employees = [Employee]()

do {
    let content = try String(contentsOfFile: filePath, encoding: .utf8)
    let lines = content.components(separatedBy: .newlines).filter { !$0.isEmpty }

    // Skip header and parse rows
    for line in lines.dropFirst() {
        let columns = line.components(separatedBy: ",")
        if columns.count >= 4 {
            let name = columns[1].trimmingCharacters(in: .whitespaces)
            let dept = columns[2].trimmingCharacters(in: .whitespaces)
            let salaryStr = columns[3].trimmingCharacters(in: .whitespaces)
            if let salary = Double(salaryStr) {
                employees.append(Employee(name: name, department: dept, salary: salary))
            }
        }
    }

    var deptSalaries = [String: [Double]]()
    var deptCounts = [String: Int]()
    var totalBudget: Double = 0
    var highestPaid: Employee?

    for emp in employees {
        deptSalaries[emp.department, default: []].append(emp.salary)
        deptCounts[emp.department, default: 0] += 1
        totalBudget += emp.salary
        if highestPaid == nil || emp.salary > highestPaid!.salary {
            highestPaid = emp
        }
    }

    // Setup formatters
    let avgFormatter = NumberFormatter()
    avgFormatter.numberStyle = .currency
    avgFormatter.currencyCode = "USD"
    avgFormatter.minimumFractionDigits = 2
    avgFormatter.maximumFractionDigits = 2
    avgFormatter.locale = Locale(identifier: "en_US")

    let intFormatter = NumberFormatter()
    intFormatter.numberStyle = .currency
    intFormatter.currencyCode = "USD"
    intFormatter.minimumFractionDigits = 0
    intFormatter.maximumFractionDigits = 0
    intFormatter.locale = Locale(identifier: "en_US")

    // Output the report
    print("=== Salary Report ===")
    print("")

    print("Average Salary by Department:")
    let sortedDepts = deptSalaries.keys.sorted()
    for dept in sortedDepts {
        let salaries = deptSalaries[dept]!
        let avg = salaries.reduce(0, +) / Double(salaries.count)
        let formattedAvg = avgFormatter.string(from: NSNumber(value: avg)) ?? "$0.00"
        print("  \(dept): \(formattedAvg)")
    }
    print("")

    if let hp = highestPaid {
        let formattedHp = intFormatter.string(from: NSNumber(value: hp.salary)) ?? "$0"
        print("Highest Paid: \(hp.name) (\(formattedHp))")
    }
    print("")

    print("Departments with >2 employees:")
    let largeDepts = deptCounts.filter { $0.value > 2 }.keys.sorted()
    for dept in largeDepts {
        print("  \(dept) (\(deptCounts[dept]!) employees)")
    }
    print("")

    let formattedTotal = intFormatter.string(from: NSNumber(value: totalBudget)) ?? "$0"
    print("Total Budget: \(formattedTotal)")

} catch {
    // Silently exit on error as per requirements
}

import * as fs from 'fs';

const logFilePath = '/tmp/…/app.log';

function runAnalysis() {
    try {
        const data = fs.readFileSync(logFilePath, 'utf8');
        const lines = data.split(/\r?\n/);

        const levelCounts: Record<string, number> = {};
        const errorCountsByComponent: Record<string, number> = {};
        const uniqueErrorMessages = new Set<string>();
        const hourCounts: Record<string, number> = {};

        // Regex to capture: [Timestamp] LEVEL (Component) - Message
        // Group 1: Timestamp (YYYY-MM-DD HH:MM:SS)
        // Group 2: Hour (HH)
        // Group 3: Level
        // Group 4: Component
        // Group 5: Message
        const logRegex = /^\[(\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.*)$/;

        for (const line of lines) {
            if (!line.trim()) continue;
            const match = line.match(logRegex);
            if (match) {
                const timestamp = match[1];
                const hour = match[2];
                const level = match[3];
                const component = match[4];
                const message = match[5];

                // Update Level counts
                levelCounts[level] = (levelCounts[level] || 0) + 1;

                // Update Error metrics
                if (level === 'ERROR') {
                    errorCountsByComponent[component] = (errorCountsByComponent[component] || 0) + 1;
                    uniqueErrorMessages.add(message);
                }

                // Update Hour counts
                hourCounts[hour] = (hourCounts[hour] || 0) + 1;
            }
        }

        // 1. Entries by Level (Sorted alphabetically)
        console.log("=== Log Analysis ===");
        console.log("");
        console.log("Entries by Level:");
        const sortedLevels = Object.keys(levelCounts).sort();
        for (const level of sortedLevels) {
            console.log(`  ${level}: ${levelCounts[level]}`);
        }
        console.log("");

        // 2. Component with Most Errors
        let maxErrors = 0;
        let mostErrorComponent = "None";
        const sortedComponents = Object.keys(errorCountsByComponent).sort();
        for (const component of sortedComponents) {
            if (errorCountsByComponent[component] > maxErrors) {
                maxErrors = errorCountsByComponent[component];
                mostErrorComponent = component;
            }
        }
        console.log(`Component with Most Errors: ${mostErrorComponent} (${maxErrors} errors)`);
        console.log("");

        // 3. Unique Error Messages (Sorted alphabetically)
        console.log("Unique Error Messages:");
        const sortedErrors = Array.from(uniqueErrorMessages).sort();
        for (const msg of sortedErrors) {
            console.log(`  - ${msg}`);
        }
        console.log("");

        // 4. Busiest Hour (HH:00)
        let maxHourCount = 0;
        let busiestHour = "00";
        const sortedHours = Object.keys(hourCounts).sort();
        for (const hour of sortedHours) {
            if (hourCounts[hour] > maxHourCount) {
                maxHourCount = hourCounts[hour];
                busiestHour = hour;
            }
        }
        const formattedBusiestHour = busiestHour.padStart(2, '0') + ':00';
        console.log(`Busiest Hour: ${formattedBusiestHour} (${maxHourCount} entries)`);

    } catch (err) {
        // Fail silently to ensure no extra output is produced
    }
}

