import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String path = "/tmp/…/app.log";
        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrors = new HashMap<>();
        TreeSet<String> uniqueErrorMessages = new TreeSet<>();
        Map<Integer, Integer> hourCounts = new HashMap<>();

        try (BufferedReader br = Files.newBufferedReader(Paths.get(path))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.trim().isEmpty()) continue;

                int closingBracket = line.indexOf("] ");
                if (closingBracket == -1) continue;

                String timestamp = line.substring(1, closingBracket);
                String rest = line.substring(closingBracket + 2);

                int firstSpace = rest.indexOf(" ");
                if (firstSpace == -1) continue;
                String level = rest.substring(0, firstSpace);

                int openParen = rest.indexOf("(");
                int closeParen = rest.indexOf(")");
                if (openParen == -1 || closeParen == -1) continue;
                String component = rest.substring(openParen + 1, closeParen);

                int dashIndex = rest.indexOf(" - ");
                if (dashIndex == -1) continue;
                String message = rest.substring(dashIndex + 3);

                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);

                if ("ERROR".equals(level)) {
                    componentErrors.put(component, componentErrors.getOrDefault(component, 0) + 1);
                    uniqueErrorMessages.add(message);
                }

                if (timestamp.length() >= 13) {
                    try {
                        int hour = Integer.parseInt(timestamp.substring(11, 13));
                        hourCounts.put(hour, hourCounts.getOrDefault(hour, 0) + 1);
                    } catch (NumberFormatException e) {
                        // Ignore malformed hours
                    }
                }
            }
        } catch (IOException e) {
            // File not found or inaccessible
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();

        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
        System.out.println();

        String maxComp = "None";
        int maxErrors = 0;
        for (Map.Entry<String, Integer> entry : componentErrors.entrySet()) {
            if (entry.getValue() > maxErrors) {
                maxErrors = entry.getValue();
                maxComp = entry.getKey();
            }
        }
        System.out.println("Component with Most Errors: " + maxComp + " (" + maxErrors + " errors)");
        System.out.println();

        System.out.println("Unique Error Messages:");
        for (String msg : uniqueErrorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();

        int maxHour = -1;
        int maxHourCount = -1;
        for (Map.Entry<Integer, Integer> entry : hourCounts.entrySet()) {
            if (entry.getValue() > maxHourCount) {
                maxHourCount = entry.getValue();
                maxHour = entry.getKey();
            }
        }

        if (maxHour != -1) {
            System.out.printf("Busiest Hour: %02d:00 (%d entries)%n", maxHour, maxHourCount);
        }
    }
}

