import Foundation

/// Compares two JSON values for equality.
func areEqual(_ a: Any, _ b: Any) -> Bool {
    if let aStr = a as? String, let bStr = b as? String {
        return aStr == bStr
    }
    if let aNum = a as? NSNumber, let bNum = b as? NSNumber {
        return aNum.doubleValue == bNum.doubleValue
    }
    if let aBool = a as? Bool, let bBool = b as? Bool {
        return aBool == bBool
    }
    if let aDict = a as? [String: Any], let bDict = b as? [String: Any] {
        if aDict.count != bDict.count { return false }
        for (k, v) in aDict {
            guard let bv = bDict[k] else { return false }
            if !areEqual(v, bv) { return false }
        }
        return true
    }
    if let aArr = a as? [Any], let bArr = b as? [Any] {
        if aArr.count != bArr.count { return false }
        for i in 0..<aArr.count {
            if !areEqual(aArr[i], bArr[i]) { return false }
        }
        return true
    }
    return false
}

/// Recursively merges two JSON values based on the specified rules.
func merge(_ a: Any, _ b: Any) -> Any {
    if let dictA = a as? [String: Any], let dictB = b as? [String: Any] {
        var result = dictA
        for (key, valueB) in dictB {
            if let valueA = result[key] {
                result[key] = merge(valueA, valueB)
            } else {
                result[key] = valueB
            }
        }
        return result
    } else if let arrA = a as? [Any], let arrB = b as? [Any] {
        var result = arrA
        for item in arrB {
            var exists = false
            for existing in result {
                if areEqual(existing, item) {
                    exists = true
                    break
                }
            }
            if !exists {
                result.append(item)
            }
        }
        return result
    } else {
        // Scalar conflict or mismatched types: B overrides A
        return b
    }
}

/// Converts a JSON value into a pretty-printed string with sorted keys.
func jsonToString(_ value: Any, indentLevel: Int = 0) -> String {
    let indent = String(repeating: "  ", count: indentLevel)
    let nextIndent = String(repeating: "  ", count: indentLevel + 1)

    if let dict = value as? [String: Any] {
        let sortedKeys = dict.keys.sorted()
        if sortedKeys.isEmpty { return "{}" }
        var lines = ["{"]
        for (index, key) in sortedKeys.enumerated() {
            let val = dict[key]!
            let jsonVal = jsonToString(val, indentLevel: indentLevel + 1)
            let comma = index == sortedKeys.count - 1 ? "" : ","
            lines.append("\(nextIndent)\"\(key)\": \(jsonVal)\(comma)")
        }
        lines.append("\(indent)}")
        return lines.joined(separator: "\n")
    } else if let arr = value as? [Any] {
        if arr.isEmpty { return "[]" }
        var lines = ["["]
        for (index, item) in arr.enumerated() {
            let jsonVal = jsonToString(item, indentLevel: indentLevel + 1)
            let comma = index == arr.count - 1 ? "" : ","
            lines.append("\(nextIndent)\(jsonVal)\(comma)")
        }
        lines.append("\(indent)]")
        return lines.joined(separator: "\n")
    } else if let str = value as? String {
        return "\"\(str)\""
    } else if let bool = value as? Bool {
        return bool ? "true" : "false"
    } else if let num = value as? NSNumber {
        return num.description
    } else if value is NSNull {
        return "null"
    } else {
        return "\(value)"
    }
}

