import Foundation

let path = "/tmp/…/app.log"

func solve() {
    guard let content = try? String(contentsOfFile: path, encoding: .utf8) else {
        return
    }

    var levelCounts = [String: Int]()
    var errorCounts = [String: Int]()
    var uniqueErrors = Set<String>()
    var hourCounts = [String: Int]()

    let lines = content.components(separatedBy: .newlines)

    for line in lines {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        if trimmed.isEmpty { continue }

        let parts = line.components(separatedBy: "] ")
        if parts.count < 2 { continue }

        let timestampPart = parts[0]
        let contentPart = parts[1]

        // Extract hour: [YYYY-MM-DD HH:MM:SS]
        let timeParts = timestampPart.components(separatedBy: " ")
        if timeParts.count >= 2 {
            let time = timeParts[1]
            let hour = time.components(separatedBy: ":")[0]
            let formattedHour = String(format: "%02d:00", Int(hour) ?? 0)
            hourCounts[formattedHour, default: 0] += 1
        }

        // Parse Level (component) - message
        let levelParts = contentPart.components(separatedBy: " (")
        if levelParts.count >= 2 {
            let level = levelParts[0]
            let compMsg = levelParts[1]

            if let range = compMsg.range(of: ") - ") {
                let component = String(compMsg[..<range.lowerBound])
                let message = String(compMsg[range.upperBound...])

                levelCounts[level, default: 0] += 1
                if level == "ERROR" {
                    errorCounts[component, default: 0] += 1
                    uniqueErrors.insert(message)
                }
            }
        }
    }

    print("=== Log Analysis ===")
    print("")

    print("Entries by Level:")
    let sortedLevels = levelCounts.keys.sorted()
    for level in sortedLevels {
        print("  \(level): \(levelCounts[level]!)")
    }

    print("")

    var maxErrors = 0
    var topComponent = "None"
    for (comp, count) in errorCounts {
        if count > maxErrors {
            maxErrors = count
            topComponent = comp
        } else if count == maxErrors && maxErrors > 0 {
            if comp < topComponent {
                topComponent = comp
            }
