import java.util.*;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws Exception {
        String pathA = "/tmp/…/config_a.json";
        String pathB = "/tmp/…/config_b.json";

        String contentA = new String(Files.readAllBytes(Paths.get(pathA)), StandardCharsets.UTF_8);
        String contentB = new String(Files.readAllBytes(Paths.get(pathB)), StandardCharsets.UTF_8);

        JsonReader readerA = new JsonReader(contentA);
        Object dataA = readerA.parseValue();

        JsonReader readerB = new JsonReader(contentB);
        Object dataB = readerB.parseValue();

        Object merged = merge(dataA, dataB);

        System.out.println(prettyPrint(merged, 0));
    }

    private static Object merge(Object a, Object b) {
        if (a instanceof Map && b instanceof Map) {
            Map<String, Object> mapA = (Map<String, Object>) a;
            Map<String, Object> mapB = (Map<String, Object>) b;
            TreeMap<String, Object> result = new TreeMap<>(mapA);
            for (Map.Entry<String, Object> entry : mapB.entrySet()) {
                String key = entry.getKey();
                if (result.containsKey(key)) {
                    result.put(key, merge(result.get(key), entry.getValue()));
                } else {
                    result.put(key, entry.getValue());
                }
            }
            return result;
        } else if (a instanceof List && b instanceof List) {
            List<Object> listA = (List<Object>) a;
            List<Object> listB = (List<Object>) b;
            List<Object> result = new ArrayList<>(listA);
            for (Object item : listB) {
                if (!result.contains(item)) {
                    result.add(item);
                }
            }
            return result;
        } else {
            return b;
        }
    }

    private static String prettyPrint(Object obj, int indent) {
        if (obj == null) return "null";
        if (obj instanceof String) {
            String s = (String) obj;
            return "\"" + s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t") + "\"";
        }
        if (obj instanceof Number) return obj.toString();
        if (obj instanceof Boolean) return obj.toString();

        StringBuilder sb = new StringBuilder();
        String space = "  ".repeat(indent);
        String nextSpace = "  ".repeat(indent + 1);

        if (obj instanceof Map) {
            Map<String, Object> map = (Map<String, Object>) obj;
            if (map.isEmpty()) return "{}";
            sb.append("{\n");
            int count = 0;
            for (Map.Entry<String, Object> entry : map.entrySet()) {
                sb.append(nextSpace).append("\"").append(entry.getKey()).append("\": ");
                sb.append(prettyPrint(entry.getValue(), indent + 1));
                if (count < map.size() - 1) sb.append(",");
                sb.append("\n");
                count++;
            }
            sb.append(space).append("}");
        } else if (obj instanceof List) {
            List<Object> list = (List<Object>) obj;
            if (list.isEmpty()) return "[]";
            sb.append("[\n");
            for (int i = 0; i < list.size(); i++) {
                sb.append(nextSpace).append(prettyPrint(list.get(i), indent + 1));
                if (i < list.size() - 1) sb.append(",");
                sb.append("\n");
            }
            sb.append(space).append("]");
        }
        return sb.toString();
    }

    static class JsonReader {
        String json;
        int pos;

        JsonReader(String json) {
            this.json = json;
            this.pos = 0;
        }

        void skipWhitespace() {
            while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) {
                pos++;
            }
        }

        Object parseValue() throws Exception {
            skipWhitespace();
            if (pos >= json.length()) return null;
            char c = json.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f' || c == 'n') return parseLiteral();
            if (Character.isDigit(c) || c == '-') return parseNumber();
            return null;
        }

        private Map<String, Object> parseObject() throws Exception {
            pos++; // {
            Map<String, Object> map = new TreeMap<>();
            skipWhitespace();
            if (pos < json.length() && json.charAt(pos) == '}') {
                pos++;
                return map;
            }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                pos++; // :
                Object value = parseValue();
                map.put(key, value);
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == '}') {
                    pos++;
                    break;
                } else {
                    pos++; // ,
                }
            }
            return map;
        }

        private List<Object> parseArray() throws Exception {
            pos++; // [
            List<Object> list = new ArrayList<>();
            skipWhitespace();
            if (pos < json.length() && json.charAt(pos) == ']') {
                pos++;
                return list;
            }
            while (true) {
                list.add(parseValue());
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ']') {
                    pos++;
                    break;
                } else {
                    pos++; // ,
                }
            }
            return list;
        }

        private String parseString() throws Exception {
            pos++; // "
            StringBuilder sb = new StringBuilder();
            while (pos < json.length() && json.charAt(pos) != '"') {
                char c = json.charAt(pos);
                if (c == '\\') {
                    pos++;
                    char escaped = json.charAt(pos);
                    if (escaped == '"') sb.append('"');
                    else if (escaped == '\\') sb.append('\\');
                    else if (escaped == '/') sb.append('/');
                    else if (escaped == 'b') sb.append('\b');
                    else if (escaped == 'f') sb.append('\f');
                    else if (escaped == 'n') sb.append('\n');
                    else if (escaped == 'r') sb.append('\r');
                    else if (escaped == 't') sb.append('\t');
                    else if (escaped == 'u') {
                        String hex = json.substring(pos + 1, pos + 5);
                        sb.append((char) Integer.parseInt(hex, 16));
                        pos += 4;
                    }
                    pos++;
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            pos++; // "
            return sb.toString();
        }

        private Number parseNumber() throws Exception {
            int start = pos;
            if (json.charAt(pos) == '-') pos++;
            while (pos < json.length() && (Character.isDigit(json.charAt(pos)) || 
                   json.charAt(pos) == '.' || json.charAt(pos) == 'e' || 
                   json.charAt(pos) == 'E' || json.charAt(pos) == '+')) {
                pos++;
            }
            String numStr = json.substring(start, pos);
            if (numStr.contains(".") || numStr.contains("e") || numStr.contains("E")) {
                return Double.parseDouble(numStr);
            } else {
                return Long.parseLong(numStr);
            }
        }

        private Object parseLiteral() throws Exception {
            skipWhitespace();
            if (json.startsWith("true", pos)) {
                pos += 4;
                return true;
            } else if (json.startsWith("false", pos)) {
                pos += 5;
                return false;
            } else if (json.startsWith("null", pos)) {
                pos += 4;
                return null;
            }
            return null;
        }
    }
}

