import json
import heapq
import os

def main():
    file_path = "/tmp/…/graph.json"

    if not os.path.exists(file_path):
        return

    with open(file_path, 'r') as f:
        data = json.load(f)

    nodes = data.get("nodes", [])
    edges = data.get("edges", [])

    # Build adjacency list for an undirected graph
    adj = {node: [] for node in nodes}
    for edge in edges:
        u = edge.get("from")
        v = edge.get("to")
        w = edge.get("weight")
        if u in adj and v in adj:
            adj[u].append((v, w))
            adj[v].append((u, w))

    # Dijkstra's algorithm
    distances = {node: float('inf') for node in nodes}
    if "A" in distances:
        distances["A"] = 0
        pq = [(0, "A")]
    else:
        pq = []

    while pq:
        current_dist, u = heapq.heappop(pq)

        if current_dist > distances[u]:
            continue

        for v, weight in adj[u]:
            distance = current_dist + weight
            if distance < distances[v]:
                distances[v] = distance
                heapq.heappush(pq, (distance, v))

    # Output the results in the specified format
    print("=== Shortest Paths from A ===")
    print()
    for node in sorted(nodes):
        dist = distances[node]
        # Formatting to match the exact requirement, keeping integer if possible
        if dist == float('inf'):
            print(f"A -> {node}: INF")
        else:
            # If the distance is a whole number, print it as an integer
            if dist == int(dist):
                print(f"A -> {node}: {int(dist)}")
            else:
                print(f"A -> {node}: {dist}")

