import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    static class Product {
        String name;
        double price;

        Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) {
        try {
            // 1. Make an HTTP GET request to the specified URL
            URL url = new URL("http://127.0.0.1:18923/api/products");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);

            if (conn.getResponseCode() == 200) {
                BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                StringBuilder body = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    body.append(line);
                }
                reader.close();

                String json = body.toString();
                List<Product> products = new ArrayList<>();

                // 2. Parse the JSON response (manual parsing since no external libraries are allowed)
                // Regex to find each object within the JSON array
                Pattern objectPattern = Pattern.compile("\\{(.*?)\\}");
                Matcher objectMatcher = objectPattern.matcher(json);

                while (objectMatcher.find()) {
                    String obj = objectMatcher.group(1);
                    String name = "";
                    double price = 0.0;

                    // Extract "name" field
                    Pattern namePattern = Pattern.compile("\"name\"\\s*:\\s*\"([^\"]+)\"");
                    Matcher nameMatcher = namePattern.matcher(obj);
                    if (nameMatcher.find()) {
                        name = nameMatcher.group(1);
                    }

                    // Extract "price" field
                    Pattern pricePattern = Pattern.compile("\"price\"\\s*:\\s*([0-9.]+)");
                    Matcher priceMatcher = pricePattern.matcher(obj);
                    if (priceMatcher.find()) {
                        price = Double.parseDouble(priceMatcher.group(1));
                    }

                    products.add(new Product(name, price));
                }

                // 3. Filter to only products where price > 50.00
                List<Product> filtered = new ArrayList<>();
                for (Product p : products) {
                    if (p.price > 50.00) {
                        filtered.add(p);
                    }
                }

                // 4. Sort filtered products by name ascending (alphabetical)
                filtered.sort(Comparator.comparing(p -> p.name));

                // 5. Print the output in the exact format specified
                double total = 0;
                System.out.println("=== Filtered Products (price > $50.00) ===");
                System.out.println();

                for (Product p : filtered) {
                    System.out.printf("%s: $%.2f%n", p.name, p.price);
                    total += p.price;
                }

                System.out.println();
                System.out.println("Count: " + filtered.size());
                System.out.printf("Total: $%.2f%n", total);

            }
        } catch (Exception e) {
            // Standard library only, handle exceptions silently to ensure no extra output
        }
    }
}

import * as fs from 'fs';

const filePath = '/tmp/…/graph.json';

function main() {
    try {
        const content = fs.readFileSync(filePath, 'utf8');
        const data = JSON.parse(content);
        const nodes = data.nodes;
        const edges = data.edges;

        const adj = new Map<string, { to: string; weight: number }[]>();
        nodes.forEach(node => adj.set(node, []));

        edges.forEach(edge => {
            if (adj.has(edge.from) && adj.has(edge.to)) {
                adj.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
                adj.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
            }
        });

        const distances = new Map<string, number>();
        nodes.forEach(node => distances.set(node, Infinity));

        if (nodes.includes("A")) {
            distances.set("A", 0);
        } else {
            return;
        }

        const visited = new Set<string>();

        while (true) {
            let u: string | null = null;
            let minDistance = Infinity;

            for (const node of nodes) {
                if (!visited.has(node)) {
                    const d = distances.get(node)!;
                    if (d < minDistance) {
                        minDistance = d;
                        u = node;
                    }
                }
            }

            if (u === null) break;

            visited.add(u);

            const neighbors = adj.get(u) || [];
            for (const neighbor of neighbors) {
                const newDist = (distances.get(u) || 0) + neighbor.weight;
                const currentDist = distances.get(neighbor.to)!;
                if (newDist < currentDist) {
                    distances.set(neighbor.to, newDist);
                }
            }
        }

        console.log("=== Shortest Paths from A ===");
        console.log("");

        nodes.sort().forEach(node => {
            const dist = distances.get(node)!;
            console.log(`A -> ${node}: ${dist === Infinity ? "Infinity" : dist}`);
        });
    } catch (err) {
        // Handle potential file or parsing errors silently
    }
}

