char *my_strdup(const char *s) {
    char *d = malloc(strlen(s) + 1);
    if (d) strcpy(d, s);
    return d;
}

char *trim(char *s) {
    while (*s == ' ' || *s == '\n' || *s == '\r') s++;
    char *end = s + strlen(s) - 1;
    while (end > s && (*end == ' ' || *end == '\n' || *end == '\r')) end--;
    *(end + 1) = '\0';
    return s;
}

void print_num_with_commas(double amount, int decimals) {
    char buf[64];
    if (decimals == 0) sprintf(buf, "%.0f", amount);
    else sprintf(buf, "%.2f", amount);

    char *dot = strchr(buf, '.');
    int int_len;
    if (dot) {
        *dot = '\0';
        int_len = strlen(buf);
    } else {
        int_len = strlen(buf);
    }

    for (int i = 0; i < int_len; i++) {
        if (i > 0 && (int_len - i) % 3 == 0) printf(",");
        putchar(buf[i]);
    }
    if (dot) printf(".%s", dot + 1);
}

