int main(void) {
    const char *filename = "/tmp/…/employees.csv";
    FILE *file = fopen(filename, "r");
    if (!file) return 1;

    Employee *employees = NULL;
    int emp_count = 0;
    int emp_capacity = 10;
    employees = malloc(sizeof(Employee) * emp_capacity);

    char line[2048];
    while (fgets(line, sizeof(line), file)) {
        if (strstr(line, "employee_id")) continue;

        char *tokens[6];
        int t_count = 0;
        char *ptr = line;
        char *token = strtok(ptr, ",");
        while (token != NULL && t_count < 6) {
            tokens[t_count++] = token;
            token = strtok(NULL, ",");
        }

        if (t_count >= 4) {
            if (emp_count >= emp_capacity) {
                emp_capacity *= 2;
                employees = realloc(employees, sizeof(Employee) * emp_capacity);
            }
            employees[emp_count].name = my_strdup(trim(tokens[1]));
            employees[emp_count].dept = my_strdup(trim(tokens[2]));
            employees[emp_count].salary = atoi(trim(tokens[3]));
            emp_count++;
        }
    }
    fclose(file);

    if (emp_count == 0) return 0;

    Department *depts = NULL;
    int dept_count = 0;
    int dept_capacity = 10;
    depts = malloc(sizeof(Department) * dept_capacity);

    for (int i = 0; i < emp_count; i++) {
        int found = -1;
        for (int j = 0; j < dept_count; j++) {
            if (strcmp(employees[i].dept, depts[j].name) == 0) {
                found = j;
                break;
            }
        }
        if (found != -1) {
            depts[found].total_salary += employees[i].salary;
            depts[found].count++;
        } else {
            if (dept_count >= dept_capacity) {
                dept_capacity *= 2;
                depts = realloc(depts, sizeof(Department) * dept_capacity);
            }
            depts[dept_count].name = my_strdup(employees[i].dept);
            depts[dept_count].total_salary = employees[i].salary;
            depts[dept_count].count = 1;
            dept_count++;
        }
    }

