    print_num_with_commas(total_budget, 0);
    printf("\n");

    for (int i = 0; i < emp_count; i++) {
        free(employees[i].name);
        free(employees[i].dept);
    }
    free(employees);
    for (int i = 0; i < dept_count; i++) {
        free(depts[i].name);
    }
    free(depts);

    return 0;
