int main(void) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) return 1;

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(18923);

    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        close(sockfd);
        return 1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        close(sockfd);
        return 1;
    }

    char *request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n";
    send(sockfd, request, strlen(request), 0);

    size_t buffer_size = 1024 * 1024;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        close(sockfd);
        return 1;
    }

    int total_received = 0;
    int bytes;
    while ((bytes = recv(sockfd, buffer + total_received, buffer_size - total_received - 1, 0)) > 0) {
        total_received += bytes;
    }
    buffer[total_received] = '\0';
    close(sockfd);

    char *json_body = strstr(buffer, "\r\n\r\n");
    if (!json_body) json_body = buffer;
    else json_body += 4;

    Product *products = malloc(sizeof(Product) * 5000);
    int count = 0;

    char *ptr = json_body;
    while ((ptr = strstr(ptr, "{\"id\":")) != NULL) {
        char *end = strchr(ptr, '}');
        if (!end) break;

        char *n_key = strstr(ptr, "\"name\":");
        char *p_key = strstr(ptr, "\"price\":");

        double price = 0.0;
        char *name_buf = NULL;

        if (n_key && n_key < end) {
            char *colon = strchr(n_key, ':');
            char *q1 = strchr(colon, '\"');
            char *q2 = strchr(q1 + 1, '\"');
            if (q1 && q2) {
                int len = q2 - (q1 + 1);
                name_buf = malloc(len + 1);
                if (name_buf) {
                    strncpy(name_buf, q1 + 1, len);
                    name_buf[len] = '\0';
                }
            }
        }

        if (p_key && p_key < end) {
            char *colon = strchr(p_key, ':');
            if (colon) {
                price = atof(colon + 1);
            }
        }

        if (price > 50.00 && name_buf) {
            products[count].name = name_buf;
            products[count].price = price;
            count++;
        } else {
            if (name_buf) free(name_buf);
        }

        ptr = end + 1;
    }

    qsort(products, count, sizeof(Product), compare_products);

    printf("=== Filtered Products (price > $50.00) ===\n\n");
    double total_price = 0.0;
    for (int i = 0; i < count; i++) {
        printf("%s: $%.2f\n", products[i].name, products[i].price);
        total_price += products[i].price;
    }

    printf("\nCount: %d\nTotal: $%.2f\n", count, total_price);

    for (int i = 0; i < count; i++) {
        free(products[i].name);
    }
    free(products);
    free(buffer);

    return 0;
}

