    let data = try Data(contentsOf: URL(fileURLWithPath: filePath))
    let graphData = try JSONDecoder().decode(GraphData.self, from: data)

    var adj = [String: [(node: String, weight: Double)]]()
    for node in graphData.nodes {
        adj[node] = []
    }

    for edge in graphData.edges {
        adj[edge.from]?.append((edge.to, edge.weight))
        adj[edge.to]?.append((edge.from, edge.weight))
    }

    var distances = [String: Double]()
    for node in graphData.nodes {
        distances[node] = Double.infinity
    }

    // Ensure "A" is in the distances dictionary even if not in the nodes list
    if distances["A"] == nil {
        distances["A"] = Double.infinity
    }
    distances["A"] = 0

    var unvisited = Set(graphData.nodes)
    if distances["A"] != nil && !unvisited.contains("A") {
        unvisited.insert("A")
    }

    while !unvisited.isEmpty {
        var u: String?
        var minD = Double.infinity

        for node in unvisited {
            if let d = distances[node], d < minD {
                minD = d
                u = node
            }
        }

        guard let current = u else { break }
        unvisited.remove(current)

        if distances[current] == Double.infinity { break }

        if let neighbors = adj[current] {
            for neighbor in neighbors {
                let newDist = distances[current]! + neighbor.weight
                if newDist < (distances[neighbor.node] ?? Double.infinity) {
                    distances[neighbor.node] = newDist
                }
            }
        }
    }

    print("=== Shortest Paths from A ===")
    print("")

    var allNodes = graphData.nodes
    if !allNodes.contains("A") {
        allNodes.append("A")
    }
    let sortedNodes = allNodes.sorted()

    for node in sortedNodes {
        let dist = distances[node] ?? Double.infinity
        let distString: String
        if dist == Double.infinity {
            distString = "Infinity"
        } else if dist == floor(dist) {
            distString = String(Int(dist))
        } else {
            distString = String(dist)
        }
        print("A -> \(node): \(distString)")
    }
} catch {
    // Silent catch as per requirements
}

import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String rootPathStr = "/tmp/…/project_tree";
        Path root = Paths.get(rootPathStr);

        TreeMap<String, List<FileStats>> extensionMap = new TreeMap<>();

        try {
            Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                    String fileName = file.getFileName().toString();
                    int lastDot = fileName.lastIndexOf('.');
                    String ext = (lastDot == -1) ? "" : fileName.substring(lastDot);

                    long lines = 0;
                    long chars = attrs.size();

                    try (InputStream is = Files.newInputStream(file)) {
                        byte[] buffer = new byte[8192];
                        int bytesRead;
                        while ((bytesRead = is.read(buffer)) != -1) {
                            for (int i = 0; i < bytesRead; i++) {
                                if (buffer[i] == '\n') {
                                    lines++;
                                }
                            }
                        }
                    } catch (IOException e) {
                        // Ignore files that cannot be read
                    }

                    Path relative = root.relativize(file);
                    String relPath = relative.toString().replace('\\', '/');

                    // Ensure the relative path doesn't start with "./"
                    if (relPath.startsWith("./")) {
                        relPath = relPath.substring(2);
                    }

                    extensionMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileStats(relPath, lines, chars));
                    return FileVisitResult.CONTINUE;
                }

                @Override
                public FileVisitResult visitFileFailed(Path file, IOException exc) {
                    return FileVisitResult.CONTINUE;
                }
            });
        } catch (IOException e) {
            // Root path doesn't exist or other IO error
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileStats>> entry : extensionMap.entrySet()) {
            String ext = entry.getKey();
            List<FileStats> statsList = entry.getValue();
            Collections.sort(statsList, Comparator.comparing(s -> s.relativePath));

            long extFiles = statsList.size();
            long extLines = 0;
            long extChars = 0;

            for (FileStats fs : statsList) {
                extLines += fs.lines;
                extChars += fs.chars;
            }

            System.out.println("Extension: " + ext);
            System.out.println("  Files: " + extFiles);
            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extChars);
            for (FileStats fs : statsList) {
                System.out.println("    " + fs.relativePath + ": " + fs.lines + " lines, " + fs.chars + " chars");
            }

            totalFiles += extFiles;
            totalLines += extLines;
            totalChars += extChars;
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }

    static class FileStats {
        String relativePath;
        long lines;
        long chars;

        FileStats(String relativePath, long lines, long chars) {
            this.relativePath = relativePath;
            this.lines = lines;
            this.chars = chars;
        }
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class Edge {
        String to;
        double weight;
        Edge(String to, double weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static class NodeDist {
        String n;
        double d;
        NodeDist(String n, double d) {
            this.n = n;
            this.d = d;
        }
    }

    public static void main(String[] args) {
        try {
            String path = "/tmp/…/graph.json";
            String content = Files.readString(Paths.get(path));

            // Parse nodes
            int nodesIdx = content.indexOf("\"nodes\":");
            int nodesStart = content.indexOf("[", nodesIdx);
            int nodesEnd = content.indexOf("]", nodesStart);
            String nodesStr = content.substring(nodesStart + 1, nodesEnd - 1);
            List<String> nodes = new ArrayList<>();
            if (!nodesStr.trim().isEmpty()) {
                for (String s : nodesStr.split(",")) {
                    nodes.add(s.replace("\"", "").trim());
                }
            }

            Map<String, List<Edge>> adj = new HashMap<>();
            for (String n : nodes) {
                adj.put(n, new ArrayList<>());
            }

            // Parse edges
            int edgesIdx = content.indexOf("\"edges\":");
            int edgesStart = content.indexOf("[", edgesIdx);
            int edgesEnd = content.lastIndexOf("]");
            String edgesStr = content.substring(edgesStart + 1, edgesEnd - 1);

            String[] edgeObjects = edgesStr.split("\\},\\s*\\{");
            for (String obj : edgeObjects) {
                String cleaned = obj.replaceAll("[{}\"]", "");
                String[] pairs = cleaned.split(",");
                String from = "", to = "";
                double weight = 0;
                for (String pair : pairs) {
                    String[] kv = pair.split(":");
                    if (kv.length < 2) continue;
                    String key = kv[0].trim();
                    String val = kv[1].trim();
                    if (key.equals("from")) from = val;
                    else if (key.equals("to")) to = val;
                    else if (key.equals("weight")) weight = Double.parseDouble(val);
                }
                if (!from.isEmpty() && !to.isEmpty() && adj.containsKey(from) && adj.containsKey(to)) {
                    adj.get(from).add(new Edge(to, weight));
                    adj.get(to).add(new Edge(from, weight));
                }
            }

            // Dijkstra's Algorithm
            Map<String, Double> dist = new HashMap<>();
            for (String n : nodes) {
                dist.put(n, Double.POSITIVE_INFINITY);
            }
            if (adj.containsKey("A")) {
                dist.put("A", 0.0);
                PriorityQueue<NodeDist> pq = new PriorityQueue<>(Comparator.comparingDouble(nd -> nd.d));
                pq.add(new NodeDist("A", 0.0));

                while (!pq.isEmpty()) {
                    NodeDist current = pq.poll();
                    String u = current.n;
                    double d = current.d;

                    if (d > dist.get(u)) continue;

                    for (Edge e : adj.get(u)) {
                        if (dist.get(u) + e.weight < dist.get(e.to)) {
                            dist.put(e.to, dist.get(u) + e.weight);
                            pq.add(new NodeDist(e.to, dist.get(e.to)));
                        }
                    }
                }
            } else {
                // If "A" is not in the graph, distance to everything except A is Infinity
                // But the prompt implies "A" is a node.
            }

            // Output results
            System.out.println("=== Shortest Paths from A ===");
            System.out.println();
            Collections.sort(nodes);
            for (String n : nodes) {
                double d = dist.getOrDefault(n, Double.POSITIVE_INFINITY);
                String dStr = String.valueOf(d);
                if (dStr.endsWith(".0")) {
                    dStr = dStr.substring(0, dStr.length() - 2);
                }
                System.out.println("A -> " + n + ": " + dStr);
            }

        } catch (Exception e) {
            // Expected to run to completion without errors
        }
    }
}

