int compare_pairs(const void *a, const void *b) {
            const JSONPair *pa = (const JSONPair *)a;
            const JSONPair *pb = (const JSONPair *)b;
            return strcmp(pa->key, pb->key);
        }

int json_equals(JSONValue *v1, JSONValue *v2) {
            if (v1->type != v2->type) return 0;
            switch (v1->type) {
                case JSON_NULL: return 1;
                case JSON_BOOL: return v1->data.boolean == v2->data.boolean;
                case JSON_NUMBER: return v1->data.number == v2->data.number;
                case JSON_STRING: return strcmp(v1->data.string, v2->data.string) == 0;
                case JSON_ARRAY:
                    if (v1->data.array.count != v2->data.array.count) return 0;
                    for (size_t i = 0; i < v1->data.array.count; i++) {
                        if (!json_equals(v1->data.array.items[i], v2->data.array.items[i])) return 0;
                    }
                    return 1;
                case JSON_OBJECT:
                    if (v1->data.object.count != v2->data.object.count) return 0;
                    for (size_t i = 0; i < v1->data.object.count; i++) {
                        // Since they are sorted, we can compare them directly
                        if (strcmp(v1->data.object.pairs[i].key, v2->data.object.pairs[i].key) != 0) return 0;
                        if (!json_equals(v1->data.object.pairs[i].value, v2->data.object.pairs[i].value)) return 0;
                    }
                    return 1;
            }
            return 0;
        }

void json_free(JSONValue *v) {
            if (!v) return;
            if (v->type == JSON_STRING) {
                free(v->data.string);
            } else if (v->type == JSON_ARRAY) {
                for (size_t i = 0; i < v->data.array.count; i++) {
                    json_free(v->data.array.items[i]);
                }
                free(v->data.array.items);
            } else if (v->type == JSON_OBJECT) {
                for (size_t i = 0; i < v->data.object.count; i++) {
                    free(v->data.object.pairs[i].key);
                    json_free(v->data.object.pairs[i].value);
                }
                free(v->data.object.pairs);
            }
            free(v);
        }

JSONValue* json_copy(JSONValue *v) {
            if (!v) return NULL;
            JSONValue *new_v = malloc(sizeof(JSONValue));
            new_v->type = v->type;
            if (v->type == JSON_NULL) {
                new_v->data.number = 0; // Not used but for safety
            } else if (v->type == JSON_BOOL) {
                new_v->data.boolean = v->data.boolean;
            } else if (v->type == JSON_NUMBER) {
                new_v->data.number = v->data.number;
            } else if (v->type == JSON_STRING) {
                new_v->data.string = strdup(v->data.string);
            } else if (v->type == JSON_ARRAY) {
                new_v->data.array.count = v->data.array.count;
                new_v->data.array.items = malloc(sizeof(JSONValue*) * v->data.array.count);
                for (size_t i = 0; i < v->data.array.count; i++) {
                    new_v->data.array.items[i] = json_copy(v->data.array.items[i]);
                }
            } else if (v->type == JSON_OBJECT) {
                new_v->data.object.count = v->data.object.count;
                new_v->data.object.pairs = malloc(sizeof(JSONPair) * v->data.object.count);
                for (size_t i = 0; i < v->data.object.count; i++) {
                    new_v->data.object.pairs[i].key = strdup(v->data.object.pairs[i].key);
                    new_v->data.object.pairs[i].value = json_copy(v->data.object.pairs[i].value);
                }
            }
            return new_v;
        }

int find_key_index(JSONValue *obj, const char *key) {
            for (size_t i = 0; i < obj->data.object.count; i++) {
                if (strcmp(obj->data.object.pairs[i].key, key) == 0) return (int)i;
            }
            return -1;
        }

JSONValue* merge_recursive(JSONValue *a, JSONValue *b) {
            if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
                JSONValue *new_obj = malloc(sizeof(JSONValue));
                new_obj->type = JSON_OBJECT;
                new_obj->data.object.count = a->data.object.count;
                new_obj->data.object.pairs = malloc(sizeof(JSONPair) * a->data.object.count);
                for (size_t i = 0; i < a->data.object.count; i++) {
                    new_obj->data.object.pairs[i].key = strdup(a->data.object.pairs[i].key);
                    new_obj->data.object.pairs[i].value = json_copy(a->data.object.pairs[i].value);
                }

                for (size_t i = 0; i < b->data.object.count; i++) {
                    JSONPair *pb = &b->data.object.pairs[i];
                    int idx = find_key_index(new_obj, pb->key);
                    if (idx != -1) {
                        JSONValue *v_a = new_obj->data.object.pairs[idx].value;
                        if (v_a->type == JSON_OBJECT && pb->value->type == JSON_OBJECT) {
                            JSONValue *merged = merge_recursive(v_a, pb->value);
                            json_free(v_a);
                            new_obj->data.object.pairs[idx].value = merged;
                        } else if (v_a->type == JSON_ARRAY && pb->value->type == JSON_ARRAY) {
                            JSONValue *merged = merge_recursive(v_a, pb->value);
                            json_free(v_a);
                            new_obj->data.object.pairs[idx].value = merged;
                        } else {
                            json_free(v_a);
                            new_obj->data.object.pairs[idx].value = json_copy(pb->value);
                        }
                    } else {
                        new_obj->data.object.count++;
                        new_obj->data.object.pairs = realloc(new_obj->data.object.pairs, sizeof(JSONPair) * new_obj->data.object.count);
                        new_obj->data.object.pairs[new_obj->data.object.count - 1].key = strdup(pb->key);
                        new_obj->data.object.pairs[new_obj->data.object.count - 1].value = json_copy(pb->value);
                    }
                }
                qsort(new_obj->data.object.pairs, new_obj->data.object.count, sizeof(JSONPair), compare_pairs);
                return new_obj;
            } else if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
                JSONValue *new_arr = malloc(sizeof(JSONValue));
                new_arr->type = JSON_ARRAY;
                new_arr->data.array.count = a->data.array.count;
                new_arr->data.array.items = malloc(sizeof(JSONValue*) * a->data.array.count);
                for (size_t i = 0; i < a->data.array.count; i++) {
                    new_arr->data.array.items[i] = json_copy(a->data.array.items[i]);
                }

                for (size_t i = 0; i < b->data.array.count; i++) {
                    JSONValue *v_b = b->data.array.items[i];
                    int found = 0;
                    for (size_t j = 0; j < new_arr->data.array.count; j++) {
                        if (json_equals(new_arr->data.array.items[j], v_b)) {
                            found = 1;
                            break;
                        }
                    }
                    if (!found) {
                        new_arr->data.array.count++;
                        new_arr->data.array.items = realloc(new_arr->data.array.items, sizeof(JSONValue*) * new_arr->data.array.count);
                        new_arr->data.array.items[new_arr->data.array.count - 1] = json_copy(v_b);
                    }
                }
                return new_arr;
            } else {
                return json_copy(b);
            }
        }

