char* parse_string(char **ptr) {
            (*ptr)++; // skip "
            char *buf = malloc(1024); // Should be dynamic
            int len = 0;
            while ((*ptr)[0] != '\"') {
                if ((*ptr)[0] == '\\') {
                    (*ptr)++;
                    if ((*ptr)[0] == '\"') buf[len++] = '\"';
                    else if ((*ptr)[0] == '\\') buf[len++] = '\\';
                    else if ((*ptr)[0] == '/') buf[len++] = '/';
                    else if ((*ptr)[0] == 'b') buf[len++] = '\b';
                    else if ((*ptr)[0] == 'f') buf[len++] = '\f';
                    else if ((*ptr)[0] == 'n') buf[len++] = '\n';
