            v->data.number = val;
            return v;
        }

JSONValue* parse_bool(char **ptr) {
            if (strncmp(*ptr, "true", 4) == 0) {
                *ptr += 4;
                JSONValue *v = malloc(sizeof(JSONValue));
                v->type = JSON_BOOL;
                v->data.boolean = 1;
                return v;
            } else {
                *ptr += 5;
                JSONValue *v = malloc(sizeof(JSONValue));
                v->type = JSON_BOOL;
                v->data.boolean = 0;
                return v;
            }
        }

JSONValue* parse_object(char **ptr) {
            (*ptr)++; // skip {
            JSONValue *v = malloc(sizeof(JSONValue));
            v->type = JSON_OBJECT;
            v->data.object.count = 0;
            v->data.object.pairs = NULL;

            while (**ptr != '}') {
                skip_whitespace(ptr);
                if (**ptr == '}') break;

                char *key = parse_string(ptr);
                skip_whitespace(ptr);
                (*ptr)++; // skip :
                skip_whitespace(ptr);
                JSONValue *val = parse_value(ptr);

                v->data.object.count++;
                v->data.object.pairs = realloc(v->data.object.pairs, sizeof(JSONPair) * v->data.object.count);
                v->data.object.pairs[v->data.object.count - 1].key = key;
                v->data.object.pairs[v->data.object.count - 1].value = val;

                skip_whitespace(ptr);
                if (**ptr == ',') {
                    (*ptr)++;
                    skip_whitespace(ptr);
                }
            }
            (*ptr)++; // skip }
            return v;
        }

new_v->data.array.items = malloc(sizeof(JSONValue*) * v->data.array.count);
        for (size_t i = 0; i < v->data.array.count; i++) {
            new_v->data.array.items[i] = json_copy(v->data.array.items[i]);
        }

new_v->data.object.pairs = malloc(sizeof(JSONPair) * v->data.object.count);
        for (size_t i = 0; i < v->data.object.count; i++) {
            new_v->data.object.pairs[i].key = strdup(v->data.object.pairs[i].key);
            new_v->data.object.pairs[i].value = json_copy(v->data.object.pairs[i].value);
        }

if (strncmp(*ptr, "null", 4) == 0) {
            *ptr += 4;
            JSONValue *v = malloc(sizeof(JSONValue));
            v->type = JSON_NULL;
            return v;
        }

printf("[\n");
        for (size_t i = 0; i < v->data.array.count; i++) {
            for (int j = 0; j < indent; j++) printf("  ");
            json_print(v->data.array.items[i], indent + 1);
            if (i < v->data.array.count - 1) printf(",");
            printf("\n");
        }
        for (int j = 0; j < indent; j++) printf("  ");
        printf("]");

printf("{\n");
        for (size_t i = 0; i < v->data.object.count; i++) {
            for (int j = 0; j < indent; j++) printf("  ");
