            json_print(v->data.object.pairs[i].value, indent + 1);
            if (i < v->data.object.count - 1) printf(",");
            printf("\n");
        }
        for (int j = 0; j < indent; j++) printf("  ");
        printf("}");

use std::collections::{HashMap, HashSet};
use std::fs::File;
use std::io::{BufRead, BufReader};

fn main() {
    let path = "/tmp/…/app.log";
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = BufReader::new(file);

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut component_error_counts: HashMap<String, usize> = HashMap::new();
    let mut unique_error_messages: HashSet<String> = HashSet::new();
    let mut hour_counts: HashMap<String, usize> = HashMap::new();

    for line_result in reader.lines() {
        let line = match line_result {
            Ok(l) => l,
            Err(_) => continue,
        };
        if line.is_empty() {
            continue;
        }

        if let Some(end_bracket) = line.find(']') {
            let timestamp = &line[1..end_bracket];
            // Timestamp format: [YYYY-MM-DD HH:MM:SS]
            // The hour is at index 11 and 12
            if timestamp.len() >= 13 {
                let hour = &timestamp[11..13];
                *hour_counts.entry(hour.to_string()).or_insert(0) += 1;
            }

            let remainder = &line[end_bracket + 2..]; // Skip "] "
            let parts: Vec<&str> = remainder.splitn(3, ' ').collect();
            if parts.len() == 3 {
                let level = parts[0];
                let component_raw = parts[1];
                let message = parts[2].trim_start_matches("- ").trim();

                *level_counts.entry(level.to_string()).or_insert(0) += 1;

                if *level == "ERROR" {
                    let component = component_raw.trim_matches('(').trim_matches(')');
                    *component_error_counts.entry(component.to_string()).or_insert(0) += 1;
                    unique_error_messages.insert(message.to_string());
                }
            }
        }
    }

    println!("=== Log Analysis ===");
    println!();

    println!("Entries by Level:");
    let mut sorted_levels: Vec<_> = level_counts.keys().collect();
    sorted_levels.sort();
    for level in sorted_levels {
        println!("  {}: {}", level, level_counts[level]);
    }
    println!();

    let mut max_comp = "None";
    let mut max_count = 0;
    for (comp, count) in &component_error_counts {
        if *count > max_count {
            max_count = *count;
            max_comp = comp;
        }
    }
    println!("Component with Most Errors: {} ({} errors)", max_comp, max_count);
    println!();

    println!("Unique Error Messages:");
    let mut sorted_msgs: Vec<_> = unique_error_messages.iter().collect();
    sorted_msgs.sort();
    for msg in sorted_msgs {
        println!("  - {}", msg);
    }
    println!();

    let mut max_hour = "00";
    let mut max_hour_count = 0;
    for (hour, count) in &hour_counts {
        if *count > max_hour_count {
            max_hour_count = *count;
            max_hour = hour;
        }
    }
    println!("Busiest Hour: {}:00 ({} entries)", max_hour, max_hour_count);
}

