use std::collections::HashMap;
use std::fs::File;
use std::io::{BufRead, BufReader};

fn format_num(val: f64, is_avg: bool) -> String {
    let s = if is_avg {
        format!("{:.2}", val)
    } else {
        format!("{:.0}", val)
    };
    let parts: Vec<&str> = s.split('.').collect();
    let integer_part = parts[0];
    let decimal_part = if parts.len() > 1 { parts[1] } else { "".to_string() };

    let mut result = String::new();
    let bytes = integer_part.as_bytes();
    let len = bytes.len();
    for (i, &byte) in bytes.iter().enumerate() {
        result.push(byte as char);
        if i < len - 1 && (len - 1 - i) % 3 == 0 {
            result.push(',');
        }
    }

    if is_avg {
        format!("${}.{}", result, decimal_part)
    } else {
        format!("${}", result)
    }
}

fn main() {
    let path = "/tmp/…/employees.csv";
    let file = File::open(path).expect("Could not open file");
    let reader = BufReader::new(file);

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary = -1.0;
    let mut total_budget = 0.0;

    let mut lines = reader.lines();
    // Skip header
    let _ = lines.next();

    for line in lines {
        let l = line.expect("Could not read line");
        if l.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = l.split(',').collect();
        if parts.len() < 4 {
            continue;
        }

        let name = parts[1].trim().to_string();
        let dept = parts[2].trim().to_string();
        let salary: f64 = parts[3].trim().parse().unwrap_or(0.0);

        dept_salaries.entry(dept.clone()).or_insert(Vec::new()).push(salary);
        total_budget += salary;

        if salary > highest_paid_salary {
            highest_paid_salary = salary;
            highest_paid_name = name;
        }
    }

    let mut depts: Vec<String> = dept_salaries.keys().cloned().collect();
    depts.sort();

    println!("=== Salary Report ===\n");

    println!("Average Salary by Department:");
    for dept in &depts {
        let salaries = &dept_salaries[dept];
        let sum: f64 = salaries.iter().sum();
        let avg = sum / salaries.len() as f64;
        println!("  Department: {}", format_num(avg, true));
    }

    println!();
    println!("Highest Paid: {} ({})", highest_paid_name, format_num(highest_paid_salary, false));

    println!();
    println!("Departments with >2 employees:");
    for dept in &depts {
        let salaries = &dept_salaries[dept];
        if salaries.len() > 2 {
            println!("  {} ({} employees)", dept, salaries.len());
        }
    }

    println!();
    println!("Total Budget: {}", format_num(total_budget, false));
}

