use std::collections::{HashMap, BinaryHeap};
use std::cmp::Ordering;
use std::fs;

#[derive(Copy, Clone, Eq, PartialEq)]
struct State {
    cost: u64,
    node_idx: usize,
}

impl Ord for State {
    fn cmp(&self, other: &Self) -> Ordering {
        other.cost.cmp(&self.cost)
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn extract_string(obj: &str, key: &str) -> Option<String> {
    let key_str = format!("\"{}\"", key);
    if let Some(key_pos) = obj.find(&key_str) {
        let rest = &obj[key_pos + key_str.len()..];
        if let Some(colon_pos) = rest.find(':') {
            let rest = &rest[colon_pos + 1..];
            if let Some(quote_pos) = rest.find('"') {
                let rest = &rest[quote_pos + 1..];
                if let Some(end_quote_pos) = rest.find('"') {
                    return Some(rest[..end_quote_pos].to_string());
                }
            }
        }
    }
    None
}

fn extract_weight(obj: &str, key: &str) -> Option<u64> {
    let key_str = format!("\"{}\"", key);
    if let Some(key_pos) = obj.find(&key_str) {
        let rest = &obj[key_pos + key_str.len()..];
        if let Some(colon_pos) = rest.find(':') {
            let rest = &rest[colon_pos + 1..];
            let trimmed = rest.trim();
            if let Ok(val) = trimmed.parse::<u64>() {
                return Some(val);
            }
        }
    }
    None
}

fn main() {
    let path = "/tmp/…/graph.json";
    let content = fs::read_to_string(path).expect("Could not read file");

    let mut nodes = Vec::new();
    if let Some(start) = content.find("\"nodes\": [") {
        let rest = &content[start + 10..];
        if let Some(end) = rest.find(']') {
            let nodes_str = &rest[..end];
            nodes = nodes_str
                .split(',')
                .map(|s| s.trim().trim_matches('"').to_string())
                .filter(|s| !s.is_empty())
                .collect();
        }
    }

    let mut edges = Vec::new();
    if let Some(start) = content.find("\"edges\": [") {
        let rest = &content[start + 10..];
        if let Some(end) = rest.find(']') {
            let edges_str = &rest[..end];
            let parts = edges_str.split('{').skip(1);
            for part in parts {
                if let Some(obj) = part.split('}').next() {
                    let from = extract_string(obj, "from");
                    let to = extract_string(obj, "to");
                    let weight = extract_weight(obj, "weight");
                    if let (Some(f), Some(t), Some(w)) = (from, to, weight) {
                        edges.push((f, t, w));
                    }
                }
            }
        }
    }

    let mut adj = HashMap::new();
    for node in &nodes {
        adj.insert(node.clone(), Vec::new());
    }
    for (f, t, w) in edges {
        if let Some(neighbors) = adj.get_mut(&f) {
            neighbors.push((t.clone(), w));
        }
        if let Some(neighbors) = adj.get_mut(&t) {
            neighbors.push((f.clone(), w));
        }
    }

    let mut node_to_idx = HashMap::new();
    for (i, node) in nodes.iter().enumerate() {
        node_to_idx.insert(node.clone(), i);
    }

    let mut dists = vec![u64::MAX; nodes.len()];
    let mut pq = BinaryHeap::new();

    if let Some(&start_idx) = node_to_idx.get("A") {
        dists[start_idx] = 0;
        pq.push(State { cost: 0, node_idx: start_idx });
    }

    while let Some(State { cost, node_idx }) = pq.pop() {
        if cost > dists[node_idx] {
            continue;
        }
        let u_name = &nodes[node_idx];
        if let Some(neighbors) = adj.get(u_name) {
            for (v_name, weight) in neighbors {
                if let Some(&v_idx) = node_to_idx.get(v_name) {
                    let next_dist = cost + weight;
                    if next_dist < dists[v_idx] {
                        dists[v_idx] = next_dist;
                        pq.push(State { cost: next_dist, node_idx: v_idx });
                    }
                }
            }
        }
    }

    let mut results = Vec::new();
    for (i, node_name) in nodes.iter().enumerate() {
        results.push((node_name.clone(), dists[i]));
    }
    results.sort_by(|a, b| a.0.cmp(&b.0));

    println!("=== Shortest Paths from A ===");
    println!();
    for (name, dist) in results {
        println!("A -> {}: {}", name, dist);
    }
}

use std::io::{Read, Write};
use std::net::TcpStream;

#[derive(Debug)]
struct Product {
    name: String,
    price: f64,
}

fn main() {
    // Connect to the server
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect to server");

    // Construct and send the HTTP GET request
    let request = "GET /api/products HTTP/1.1\r\n\
                   Host: 127.0.0.1:18923\r\n\
                   Connection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to write request");

    // Read the entire response
    let mut buffer = Vec::new();
    stream.read_to_end(&mut buffer).expect("Failed to read response");

    // Convert buffer to string and find the start of the JSON body
    let response_str = String::from_utf8_lossy(&buffer);
    let body_start = response_str.find("\r\n\r\n").map(|i| i + 4).unwrap_or(0);
    let body = &response_str[body_start..];

    // Parse the JSON array manually to extract products
    let mut products = Vec::new();
    let body_trimmed = body.trim();
    if body_trimmed.starts_with('[') && body_trimmed.ends_with(']') {
        let content = &body_trimmed[1..body_trimmed.len() - 1];
        let mut current_pos = 0;
        while let Some(start) = content[current_pos..].find('{') {
            let start_idx = current_pos + start;
            if let Some(end_idx) = content[start_idx..].find('}') {
                let obj_str = &content[start_idx..start_idx + end_idx];

                let name = extract_value(obj_str, "\"name\":");
                let price_str = extract_value(obj_str, "\"price\":");

                if let (Some(n), Some(p_str)) = (name, price_str) {
                    if let Ok(p) = p_str.parse::<f64>() {
                        products.push(Product { name: n, price: p });
                    }
                }
                current_pos = start_idx + end_idx + 1;
            } else {
                break;
            }
        }
    }

    // Filter products where price > 50.00
    let mut filtered: Vec<Product> = products.into_iter()
        .filter(|p| p.price > 50.0)
        .collect();

    // Sort products by name ascending (alphabetical)
    filtered.sort_by(|a, b| a.name.cmp(&b.name));

    // Output the results in the specified format
    println!("=== Filtered Products (price > $50.00) ===");
    println!();

    let mut total = 0.0;
    for p in &filtered {
        println!("{}: ${:.2}", p.name, p.price);
        total += p.price;
    }

    println!();
    println!("Count: {}", filtered.len());
    println!("Total: ${:.2}", total);
}

/// Helper function to extract a value from a JSON-like object string by key
fn extract_value(obj: &str, key: &str) -> Option<String> {
    let key_pos = obj.find(key)?;
    let part = &obj[key_pos + key.len()..];

    // Skip whitespace and colon
    let mut i = 0;
    while i < part.len() && (part[i].is_whitespace() || part[i] == ':') {
        i += 1;
    }

    let start = i;
    // Find the end of the value (comma, closing brace, or whitespace)
    while i < part.len() && !part[i].is_whitespace() && part[i] != ',' && part[i] != '}' {
        i += 1;
    }

    let mut val = part[start..i].to_string();
    // Strip quotes if it's a string value
    if val.starts_with('"') && val.ends_with('"') {
        val = val[1..val.len() - 1].to_string();
    }

    Some(val)
}

