    let body_start = response_str.find("\r\n\r\n").map(|i| i + 4).unwrap_or(0);
    let body = &response_str[body_start..];

    // Parse the JSON array manually to extract products
    let mut products = Vec::new();
    let body_trimmed = body.trim();
    if body_trimmed.starts_with('[') && body_trimmed.ends_with(']') {
        let content = &body_trimmed[1..body_trimmed.len() - 1];
        let mut current_pos = 0;
        while let Some(start) = content[current_pos..].find('{') {
            let start_idx = current_pos + start;
            if let Some(end_idx) = content[start_idx..].find('}') {
                let obj_str = &content[start_idx..start_idx + end_idx];

                let name = extract_value(obj_str, "\"name\":");
                let price_str = extract_value(obj_str, "\"price\":");

                if let (Some(n), Some(p_str)) = (name, price_str) {
                    if let Ok(p) = p_str.parse::<f64>() {
                        products.push(Product { name: n, price: p });
                    }
                }
                current_pos = start_idx + end_idx + 1;
            } else {
                break;
            }
        }
    }

    // Filter products where price > 50.00
    let mut filtered: Vec<Product> = products.into_iter()
        .filter(|p| p.price > 50.0)
        .collect();

    // Sort products by name ascending (alphabetical)
    filtered.sort_by(|a, b| a.name.cmp(&b.name));

    // Output the results in the specified format
    println!("=== Filtered Products (price > $50.00) ===");
    println!();

    let mut total = 0.0;
    for p in &filtered {
        println!("{}: ${:.2}", p.name, p.price);
        total += p.price;
    }

    println!();
    println!("Count: {}", filtered.len());
    println!("Total: ${:.2}", total);
}

/// Helper function to extract a value from a JSON-like object string by key
fn extract_value(obj: &str, key: &str) -> Option<String> {
    let key_pos = obj.find(key)?;
    let part = &obj[key_pos + key.len()..];
    let chars: Vec<char> = part.chars().collect();

    let mut i = 0;
    while i < chars.len() && (chars[i].is_whitespace() || chars[i] == ':') {
        i += 1;
    }

    let start = i;
    while i < chars.len() && !chars[i].is_whitespace() && chars[i] != ',' && chars[i] != '}' {
        i += 1;
    }

    let mut val: String = chars[start..i].iter().collect();
    // Strip quotes if it's a string value
    if val.starts_with('"') && val.ends_with('"') {
        val = val[1..val.len() - 1].to_string();
    }

    Some(val)
}

