#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/**
 * Executes a shell command and captures its output into a dynamically allocated string.
 * The output is stripped of trailing newlines and whitespace.
 */
char* get_command_output(const char* cmd) {
    FILE* fp = popen(cmd, "r");
    if (fp == NULL) {
        return NULL;
    }

    size_t capacity = 256;
    char* output = malloc(capacity);
    if (output == NULL) {
        pclose(fp);
        return NULL;
    }
    output[0] = '\0';

    char buffer[512];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        size_t current_len = strlen(output);
        size_t buffer_len = strlen(buffer);

        if (current_len + buffer_len + 1 > capacity) {
            capacity *= 2;
            char* new_output = realloc(output, capacity);
            if (new_output == NULL) {
                free(output);
                pclose(fp);
                return NULL;
            }
            output = new_output;
        }
        strcat(output, buffer);
    }
    pclose(fp);

    // Strip trailing newlines and whitespace
    size_t len = strlen(output);
    while (len > 0 && (output[len - 1] == '\n' || output[len - 1] == '\r' || 
                        output[len - 1] == ' ' || output[len - 1] == '\t')) {
        output[len - 1] = '\0';
        len--;
    }

    return output;
}

int main(void) {
    // Execute commands and capture outputs
    char* hostname = get_command_output("hostname");
    char* os = get_command_output("uname -s");
    char* architecture = get_command_output("uname -m");
    char* username = get_command_output("whoami");

    // Provide fallbacks in case of command failure
    hostname = hostname ? hostname : "unknown";
    os = os ? os : "unknown";
    architecture = architecture ? architecture : "unknown";
    username = username ? username : "unknown";

    // Output the JSON object in the specified order and format
    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname);
    printf("  \"os\": \"%s\",\n", os);
    printf("  \"architecture\": \"%s\",\n", architecture);
    printf("  \"username\": \"%s\"\n", username);
    printf("}\n");

    // Clean up allocated memory
    free(hostname);
    free(os);
    free(architecture);
    free(username);

    return 0;
}

import Foundation

func runCommand(_ command: String) -> String {
    let process = Process()
    let pipe = Pipe()

    process.standardOutput = pipe
    process.standardError = pipe
    process.arguments = ["-c", command]
    process.executableURL = URL(fileURLWithPath: "/bin/sh")

    do {
        try process.run()
        process.waitUntilExit()
        let data = pipe.fileHandleForReading.readDataToEndOfFile()
        return String(data: data, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    } catch {
        return ""
    }
}

