    for (int i = 1; i < 24; i++) {
        if (hour_counts[i] > hour_counts[busiest_hour]) {
            busiest_hour = i;
        }
    }
    printf("Busiest Hour: %02d:00 (%d entries)\n", busiest_hour, hour_counts[busiest_hour]);

    for (int i = 0; i < levels_count; i++) free(levels[i].name);
    free(levels);
    for (int i = 0; i < components_count; i++) free(components[i].name);
    free(components);
    for (int i = 0; i < errors_count; i++) free(error_messages[i]);
    free(error_messages);

    return 0;
}

