use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

fn main() {
    let root_path = Path::new("/tmp/…/project_tree");
    let mut results: BTreeMap<String, Vec<(String, usize, usize)>> = BTreeMap::new();

    if let Ok(entries) = fs::read_dir(root_path) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_symlink() {
                continue;
            }
            if path.is_dir() {
                walk_dir(&path, root_path, &mut results);
            } else if path.is_file() {
                process_file(&path, root_path, &mut results);
            }
        }
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files = 0;
    let mut total_lines = 0;
    let mut total_chars = 0;

    for (ext, files) in results {
        let mut sorted_files = files;
        sorted_files.sort_by(|a, b| a.0.cmp(&b.0));

        let mut ext_lines = 0;
        let mut ext_chars = 0;
        for f in &sorted_files {
            ext_lines += f.1;
            ext_chars += f.2;
        }

        println!("Extension: {}", ext);
        println!("  Files: {}", sorted_files.len());
        println!("  Total Lines: {}", ext_lines);
        println!("  Total Characters: {}", ext_chars);

        for (rel_path, lines, chars) in sorted_files {
            println!("    {}: {} lines, {} chars", rel_path, lines, chars);
            total_files += 1;
            total_lines += lines;
            total_chars += chars;
        }
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

fn walk_dir(dir: &Path, root: &Path, results: &mut BTreeMap<String, Vec<(String, usize, usize)>>) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_symlink() {
                continue;
            }
            if path.is_dir() {
                walk_dir(&path, root, results);
            } else if path.is_file() {
                process_file(&path, root, results);
            }
        }
    }
}

fn process_file(path: &Path, root: &Path, results: &mut BTreeMap<String, Vec<(String, usize, usize)>>) {
    let extension = path
        .extension()
        .and_then(|s| s.to_str())
        .map(|s| format!(".{}", s))
        .unwrap_or_else(|| "(no extension)".to_string());

    let rel_path = path
        .strip_prefix(root)
        .unwrap_or(path)
        .to_string_lossy()
        .replace('\\', "/");

    if let Ok(mut file) = fs::File::open(path) {
        let mut content = Vec::new();
        if file.read_to_end(&mut content).is_ok() {
            let lines = content.iter().filter(|&&b| b == b'\n').count();
            let chars = content.len();
            results
                .entry(extension)
                .or_insert(Vec::new())
                .push((rel_path, lines, chars));
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) {
        try {
            String os = exec("uname", "-s");
            String arch = exec("uname", "-m");
            String user = exec("whoami");
            String host = exec("hostname");

            System.out.println("{");
            System.out.println("  \"hostname\": \"" + host + "\",");
            System.out.println("  \"os\": \"" + os + "\",");
            System.out.println("  \"architecture\": \"" + arch + "\",");
            System.out.println("  \"username\": \"" + user + "\"");
            System.out.println("}");
        } catch (Exception e) {
            // Catching all exceptions to ensure no stack trace is printed to stdout
        }
    }

    private static String exec(String... command) throws Exception {
        java.lang.ProcessBuilder pb = new java.lang.ProcessBuilder(command);
        pb.redirectError(java.lang.ProcessBuilder.Redirect.IN);
        java.lang.Process p = pb.start();
        java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.InputStreamReader(p.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line).append("\n");
        }
        p.waitFor();
        return sb.toString().trim();
    }
}

