use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum JsonValue {
    Object(BTreeMap<String, JsonValue>),
    Array(Vec<JsonValue>),
    String(String),
    Number(f64),
    Boolean(bool),
    Null,
}

struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input, pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_whitespace();
        if self.pos >= self.input.len() {
            return JsonValue::Null;
        }
        let c = self.input[self.pos];
        match c {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => JsonValue::String(self.parse_string()),
            't' => {
                self.pos += 4;
                JsonValue::Boolean(true)
            }
            'f' => {
                self.pos += 5;
                JsonValue::Boolean(false)
            }
            'n' => {
                self.pos += 4;
                JsonValue::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> JsonValue {
        self.pos += 1; // {
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        while self.pos < self.input.len() && self.input[self.pos] != '}' {
            let key = self.parse_string();
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == ':' {
                self.pos += 1;
            }
            self.skip_whitespace();
            let value = self.parse_value();
            map.insert(key, value);
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == ',' {
                self.pos += 1;
                self.skip_whitespace();
            }
        }
        self.pos += 1; // }
        JsonValue::Object(map)
    }

    fn parse_array(&mut self) -> JsonValue {
        self.pos += 1; // [
        let mut arr = Vec::new();
        self.skip_whitespace();
        while self.pos < self.input.len() && self.input[self.pos] != ']' {
            arr.push(self.parse_value());
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == ',' {
                self.pos += 1;
                self.skip_whitespace();
            }
        }
        self.pos += 1; // ]
        JsonValue::Array(arr)
    }

    fn parse_string(&mut self) -> String {
        self.pos += 1; // "
        let mut s = String::new();
        while self.pos < self.input.len() && self.input[self.pos] != '"' {
            let c = self.input[self.pos];
            if c == '\\' {
                self.pos += 1;
                if self.pos < self.input.len() {
                    match self.input[self.pos] {
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        _ => s.push(self.input[self.pos]),
                    }
                }
            } else {
                s.push(c);
            }
            self.pos += 1;
        }
        self.pos += 1; // "
        s
    }

    fn parse_number(&mut self) -> JsonValue {
        let start = self.pos;
        while self.pos < self.input.len() && 
              (self.input[self.pos].is_digit(10) || 
               self.input[self.pos] == '.' || 
               self.input[self.pos] == '-' || 
               self.input[self.pos] == 'e' || 
               self.input[self.pos] == 'E' ||
               self.input[self.pos] == '+') {
            self.pos += 1;
        }
        let s = &self.input[start..self.pos];
        let n = s.parse::<f64>().unwrap_or(0.0);
        JsonValue::Number(n)
    }
}

fn merge(a: JsonValue, b: JsonValue) -> JsonValue {
    match (a, b) {
        (JsonValue::Object(mut map_a), JsonValue::Object(map_b)) => {
            for (k, v_b) in map_b {
                if let Some(v_a) = map_a.remove(&k) {
                    map_a.insert(k, merge(v_a, v_b));
                } else {
                    map_a.insert(k, v_b);
                }
            }
            JsonValue::Object(map_a)
        }
        (JsonValue::Array(vec_a), JsonValue::Array(vec_b)) => {
            let mut result = Vec::new();
            for item in vec_a {
                if !result.contains(&item) {
                    result.push(item);
                }
            }
            for item in vec_b {
                if !result.contains(&item) {
                    result.push(item);
                }
            }
            JsonValue::Array(result)
        }
        (_, b_val) => b_val,
    }
}

fn serialize(val: &JsonValue, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    match val {
        JsonValue::Object(map) => {
            let mut res = String::from("{\n");
            let mut keys: Vec<_> = map.keys().collect();
            keys.sort();
            for (i, k) in keys.iter().enumerate() {
                let v = &map[k];
                res.push_str(&format!("{}  \"{}\": {}", pad, k, serialize(v, indent + 1)));
                if i < keys.len() - 1 {
                    res.push(",");
                }
                res.push("\n");
            }
            res.push_str(&pad);
            res.push("}");
            res
        }
        JsonValue::Array(arr) => {
            let mut res = String::from("[\n");
            for (i, v) in arr.iter().enumerate() {
                res.push_str(&format!("{}  {}", pad, serialize(v, indent + 1)));
                if i < arr.len() - 1 {
                    res.push(",");
                }
                res.push("\n");
            }
            res.push_str(&pad);
            res.push("]");
            res
        }
        JsonValue::String(s) => format!("\"{}\"", s),
        JsonValue::Number(n) => n.to_string(),
        JsonValue::Boolean(b) => b.to_string(),
        JsonValue::Null => "null".to_string(),
    }
}

fn main() {
    let path_a = "/tmp/…/config_a.json";
    let path_b = "/tmp/…/config_b.json";

    let content_a = fs::read_to_string(path_a).expect("Failed to read config_a.json");
    let content_b = fs::read_to_string(path_b).expect("Failed to read config_b.json");

    let mut parser_a = Parser::new(&content_a);
    let val_a = parser_a.parse_value();

    let mut parser_b = Parser::new(&content_b);
    let val_b = parser_b.parse_value();

    let merged = merge(val_a, val_b);
    println!("{}", serialize(&merged, 0));
}

use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum JsonValue {
    Object(BTreeMap<String, JsonValue>),
    Array(Vec<JsonValue>),
    String(String),
    Number(f64),
    Boolean(bool),
    Null,
}

struct Parser {
    input: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(input: &str) -> Self {
        Parser {
            input: input.chars().collect(),
            pos: 0,
        }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_whitespace();
        if self.pos >= self.input.len() {
            return JsonValue::Null;
        }
        match self.input[self.pos] {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => JsonValue::String(self.parse_string()),
            't' => {
                self.pos += 4;
                JsonValue::Boolean(true)
            }
            'f' => {
                self.pos += 5;
                JsonValue::Boolean(false)
            }
            'n' => {
                self.pos += 4;
                JsonValue::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> JsonValue {
        self.pos += 1; // {
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        while self.pos < self.input.len() && self.input[self.pos] != '}' {
            self.skip_whitespace();
            if self.pos >= self.input.len() || self.input[self.pos] == '}' {
                break;
            }
            let key = self.parse_string();
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == ':' {
                self.pos += 1;
            }
            self.skip_whitespace();
            let value = self.parse_value();
            map.insert(key, value);
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == ',' {
                self.pos += 1;
                self.skip_whitespace();
            }
        }
        self.pos += 1; // }
        JsonValue::Object(map)
    }

    fn parse_array(&mut self) -> JsonValue {
        self.pos += 1; // [
        let mut arr = Vec::new();
        self.skip_whitespace();
        while self.pos < self.input.len() && self.input[self.pos] != ']' {
            self.skip_whitespace();
            if self.pos >= self.input.len() || self.input[self.pos] == ']' {
                break;
            }
            arr.push(self.parse_value());
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == ',' {
                self.pos += 1;
                self.skip_whitespace();
            }
        }
        self.pos += 1; // ]
        JsonValue::Array(arr)
    }

    fn parse_string(&mut self) -> String {
        self.pos += 1; // "
        let mut s = String::new();
        while self.pos < self.input.len() && self.input[self.pos] != '"' {
            let c = self.input[self.pos];
            if c == '\\' {
                self.pos += 1;
                if self.pos < self.input.len() {
                    match self.input[self.pos] {
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        _ => s.push(self.input[self.pos]),
                    }
                }
            } else {
                s.push(c);
            }
            self.pos += 1;
        }
        self.pos += 1; // "
        s
    }

    fn parse_number(&mut self) -> JsonValue {
        let start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c.is_digit(10) || c == '.' || c == '-' || c == 'e' || c == 'E' || c == '+' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s = &self.input[start..self.pos];
        let n = s.parse::<f64>().unwrap_or(0.0);
        JsonValue::Number(n)
    }
}

fn merge(a: JsonValue, b: JsonValue) -> JsonValue {
    match (a, b) {
        (JsonValue::Object(mut map_a), JsonValue::Object(map_b)) => {
            for (k, v_b) in map_b {
                if let Some(v_a) = map_a.remove(&k) {
                    map_a.insert(k, merge(v_a, v_b));
                } else {
                    map_a.insert(k, v_b);
                }
            }
            JsonValue::Object(map_a)
        }
        (JsonValue::Array(vec_a), JsonValue::Array(vec_b)) => {
            let mut result = Vec::new();
            for item in vec_a {
                if !result.contains(&item) {
                    result.push(item);
                }
            }
            for item in vec_b {
                if !result.contains(&item) {
                    result.push(item);
                }
            }
            JsonValue::Array(result)
        }
        (_, b_val) => b_val,
    }
}

fn serialize(val: &JsonValue, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    match val {
        JsonValue::Object(map) => {
            let mut res = String::from("{\n");
