                    res.push(",");
                }
                res.push("\n");
            }
            res.push_str(&pad);
            res.push("}");
            res
        }
        JsonValue::Array(arr) => {
            let mut res = String::from("[\n");
            for (i, v) in arr.iter().enumerate() {
                res.push_str(&format!("{}  {}", pad, serialize(v, indent + 1)));
                if i < arr.len() - 1 {
