#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <errno.h>

typedef struct {
    char *rel_path;
    long long lines;
    long long chars;
} FileInfo;

typedef struct {
    char *ext;
    FileInfo **files;
    int file_count;
    long long total_lines;
    long long total_chars;
} ExtensionGroup;

ExtensionGroup **groups = NULL;
int group_count = 0;

int compare_groups(const void *a, const void *b) {
    ExtensionGroup *g1 = *(ExtensionGroup **)a;
    ExtensionGroup *g2 = *(ExtensionGroup **)b;
    return strcmp(g1->ext, g2->ext);
}

int compare_files(const void *a, const void *b) {
    FileInfo *f1 = *(FileInfo **)a;
    FileInfo *f2 = *(FileInfo **)b;
    return strcmp(f1->rel_path, f2->rel_path);
}

void add_file(const char *rel_path, long long lines, long long chars) {
    char *filename = strrchr(rel_path, '/');
    if (!filename) filename = rel_path;
    else filename = filename + 1;

    char *ext = strrchr(filename, '.');
    if (!ext) ext = "";

    ExtensionGroup *target = NULL;
    for (int i = 0; i < group_count; i++) {
        if (strcmp(groups[i]->ext, ext) == 0) {
            target = groups[i];
            break;
        }
    }

    if (!target) {
        groups = realloc(groups, sizeof(ExtensionGroup*) * (group_count + 1));
        target = malloc(sizeof(ExtensionGroup));
        target->ext = strdup(ext);
        target->files = NULL;
        target->file_count = 0;
        target->total_lines = 0;
        target->total_chars = 0;
        groups[group_count] = target;
        group_count++;
        qsort(groups, group_count, sizeof(ExtensionGroup*), compare_groups);
    }

    target->files = realloc(target->files, sizeof(FileInfo*) * (target->file_count + 1));
    target->files[target->file_count] = malloc(sizeof(FileInfo));
    target->files[target->file_count]->rel_path = strdup(rel_path);
    target->files[target->file_count]->lines = lines;
    target->files[target->file_count]->chars = chars;
    target->total_lines += lines;
    target->total_chars += chars;
    target->file_count++;
}

void walk_directory(const char *base_path, const char *current_path) {
    DIR *dir = opendir(current_path);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[8192];
        snprintf(full_path, sizeof(full_path), "%s/%s", current_path, entry->d_name);

        struct stat st;
        if (lstat(full_path, &st) == 0) {
            if (S_ISDIR(st.st_mode) && !S_ISLNK(st.st_mode)) {
                walk_directory(base_path, full_path);
            } else if (S_ISREG(st.st_mode) && !S_ISLNK(st.st_mode)) {
                FILE *f = fopen(full_path, "rb");
                if (f) {
                    long long lines = 0;
                    long long chars = 0;
                    unsigned char buf[8192];
                    size_t bytes_read;
                    while ((bytes_read = fread(buf, 1, sizeof(buf), f)) > 0) {
                        chars += bytes_read;
                        for (size_t i = 0; i < bytes_read; i++) {
                            if (buf[i] == '\n') lines++;
                        }
                    }
                    fclose(f);

                    size_t base_len_val = strlen(base_path);
                    const char *rel_path = full_path + base_len_val + 1;
                    add_file(rel_path, lines, chars);
                }
            }
        }
    }
    closedir(dir);
}

int main(void) {
    const char *base_path = "/tmp/…/project_tree";
    walk_directory(base_path, base_path);

    printf("=== File Tree Analysis ===\n\n");

    long long total_files = 0;
    long long total_lines = 0;
    long long total_chars = 0;

    for (int i = 0; i < group_count; i++) {
        ExtensionGroup *g = groups[i];
        qsort(g->files, g->file_count, sizeof(FileInfo*), compare_files);
        printf("Extension: %s\n", g->ext);
        printf("  Files: %d\n", g->file_count);
        printf("  Total Lines: %lld\n", g->total_lines);
        printf("  Total Characters: %lld\n", g->total_chars);
        for (int j = 0; j < g->file_count; j++) {
            printf("    %s: %lld lines, %lld chars\n", g->files[j]->rel_path, g->files[j]->lines, g->files[j]->chars);
        }
        total_files += g->file_count;
        total_lines += g->total_lines;
        total_chars += g->total_chars;
    }

    printf("\nTotal: %lld files, %lld lines, %lld characters\n", total_files, total_lines, total_chars);

    return 0;
}

