let matrixA = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
let matrixB = [[9, 8, 7], [6, 5, 4], [3, 2, 1]]

func multiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let rowsA = A.count
    let colsA = A[0].count
    let colsB = B[0].count
    var C = Array(repeating: Array(repeating: 0, count: colsB), count: rowsA)

    for i in 0..<rowsA {
        for j in 0..<colsB {
            for k in 0..<colsA {
                C[i][j] += A[i][k] * B[k][j]
            }
        }
    }
    return C
}

func determinant(_ matrix: [[Int]]) -> Int {
    let a = matrix[0][0], b = matrix[0][1], c = matrix[0][2]
    let d = matrix[1][0], e = matrix[1][1], f = matrix[1][2]
    let g = matrix[2][0], h = matrix[2][1], i = matrix[2][2]
    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

func formatMatrix(_ matrix: [[Int]]) -> String {
    var result = ""
    for row in matrix {
        let rowString = row.map { String(format: "%4d", $0) }.joined(separator: " ")
        result += "  " + rowString + "\n"
    }
    return result
}

