    int **C = (int **)malloc(rows * sizeof(int *));
    for (int i = 0; i < rows; i++) C[i] = (int *)malloc(cols * sizeof(int));

    // Define Matrix A
    int dataA[3][3] = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    // Define Matrix B
    int dataB[3][3] = {
        {9, 8, 7},
        {6, 5, 4},
        {3, 2, 1}
    };

    // Populate matrices
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            A[i][j] = dataA[i][j];
            B[i][j] = dataB[i][j];
        }
    }

    // Compute C = A x B (Standard Matrix Multiplication)
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            C[i][j] = 0;
            for (int k = 0; k < cols; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    // Compute the determinant of C (3x3 matrix)
    // Det = c00(c11*c22 - c12*c21) - c01(c10*c22 - c12*c20) + c02(c10*c21 - c11*c20)
    long long det = (long long)C[0][0] * (C[1][1] * C[2][2] - C[1][2] * C[2][1]) -
