        printf("  %4d %4d %4d\n", B[i][0], B[i][1], B[i][2]);
    }

    printf("\nA x B =\n");
    for (int i = 0; i < rows; i++) {
        printf("  %4d %4d %4d\n", C[i][0], C[i][1], C[i][2]);
    }

    printf("\nDeterminant: %lld\n", det);

    // Free allocated memory
    for (int i = 0; i < rows; i++) {
        free(A[i]);
        free(B[i]);
        free(C[i]);
    }
    free(A);
    free(B);
    free(C);

    return 0;
}

