    }
    println!();

    println!("Determinant: {}", det);
}

/**
 * This program performs matrix multiplication and determinant calculation.
 * It takes two predefined matrices A and B, computes their product C = A x B,
 * and then calculates the determinant of matrix C.
 */

const MatrixA: number[][] = [
  [1, 2, 3],
  [4, 5, 6],
  [7, 8, 9],
];

const MatrixB: number[][] = [
  [9, 8, 7],
  [6, 5, 4],
  [3, 2, 1],
];

/**
 * Multiplies two matrices A and B.
 * @param A The first matrix.
 * @param B The second matrix.
 * @returns The resulting matrix C = A x B.
 */
function multiplyMatrices(A: number[][], B: number[][]): number[][] {
  const rowsA = A.length;
  const colsA = A[0].length;
  const colsB = B[0].length;
  const result: number[][] = Array.from({ length: rowsA }, () => new Array(colsB).fill(0));

  for (let i = 0; i < rowsA; i++) {
    for (let j = 0; j < colsB; j++) {
      for (let k = 0; k < colsA; k++) {
        result[i][j] += A[i][k] * B[k][j];
      }
    }
  }
  return result;
}

/**
 * Computes the determinant of a 3x3 matrix.
 * @param M A 3x3 matrix.
 * @returns The determinant.
 */
function computeDeterminant3x3(M: number[][]): number {
  const [a, b, c] = M[0];
  const [d, e, f] = M[1];
  const [g, h, i] = M[2];

  return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
}

/**
 * Formats and prints a matrix to stdout in the specified format.
 * @param matrix The matrix to print.
 */
function printMatrix(matrix: number[][]): void {
  matrix.forEach((row) => {
    const formattedRow = "  " + row.map((v) => v.toString().padStart(4, " ")).join(" ");
    console.log(formattedRow);
  });
}

function main(): void {
  const MatrixC = multiplyMatrices(MatrixA, MatrixB);
  const determinantC = computeDeterminant3x3(MatrixC);

  console.log("=== Matrix Operations ===\n");

  console.log("Matrix A:");
  printMatrix(MatrixA);

  console.log("Matrix B:");
  printMatrix(MatrixB);

  console.log("A x B =");
  printMatrix(MatrixC);

  console.log(`Determinant: ${determinantC}`);
}

main();

